using UnityEngine;
using System.Collections.Generic;
using System.Text;

/// <summary>
/// This is a temporary dummy class for testing.
/// Generated by AI, remove before publishing
/// </summary>
public class DebugViewer : MonoBehaviour
{
    private static Dictionary<string, string> debugLogs = new Dictionary<string, string>();
    private StringBuilder sb = new StringBuilder();
    
    [Header("Settings")]
    public int fontSize = 24;
    public Color textColor = Color.green;
    public Vector2 padding = new Vector2(10, 10);

    /// <summary>
    /// Call this from ANY script to add or update a value on screen.
    /// </summary>
    public static void Log(string key, string value)
    {
        debugLogs[key] = value;
    }

    /// <summary>
    /// Removes a log from the screen when no longer needed.
    /// </summary>
    public static void RemoveLog(string key)
    {
        if (debugLogs.ContainsKey(key))
        {
            debugLogs.Remove(key);
        }
    }

    // OnGUI draws directly to the screen overlay independent of cameras or Canvases
    void OnGUI()
    {
        if (debugLogs.Count == 0) return;

        sb.Clear();
        foreach (var log in debugLogs)
        {
            sb.AppendLine($"{log.Key}: {log.Value}");
        }

        GUIStyle style = new GUIStyle();
        style.fontSize = fontSize;
        style.normal.textColor = textColor;

        // Draw a slight drop shadow for readability against bright backgrounds
        style.normal.textColor = Color.black;
        GUI.Label(new Rect(padding.x + 2, padding.y + 2, Screen.width, Screen.height), sb.ToString(), style);
        
        // Draw the actual text
        style.normal.textColor = textColor;
        GUI.Label(new Rect(padding.x, padding.y, Screen.width, Screen.height), sb.ToString(), style);
    }
}